+{"version":3,"sources":["/workspace/repo/src/__tests__/useForm/setError.test.tsx"],"sourcesContent":["import React from 'react';\nimport {\n  act,\n  fireEvent,\n  render,\n  renderHook,\n  screen,\n  waitFor,\n} from '@testing-library/react';\n\nimport type {\n  DeepMap,\n  ErrorOption,\n  FieldError,\n  GlobalError,\n} from '../../types';\nimport { useForm } from '../../useForm';\nimport { FormProvider, useFormContext } from '../../useFormContext';\n\ndescribe('setError', () => {\n  const tests: [string, ErrorOption, DeepMap<any, FieldError>][] = [\n    [\n      'should only set an error when it is not existed',\n      { type: 'test' },\n      {\n        input: {\n          type: 'test',\n          message: undefined,\n          ref: undefined,\n        },\n      },\n    ],\n    [\n      'should set error message',\n      { type: 'test', message: 'test' },\n      {\n        input: {\n          type: 'test',\n          message: 'test',\n          ref: undefined,\n          types: undefined,\n        },\n      },\n    ],\n    [\n      'should set multiple error type',\n      {\n        types: { test1: 'test1', test2: 'test2' },\n      },\n      {\n        input: {\n          types: {\n            test1: 'test1',\n            test2: 'test2',\n          },\n          ref: undefined,\n        },\n      },\n    ],\n  ];\n\n  it.each(tests)('%s', (_, input, output) => {\n    const { result } = renderHook(() => useForm<{ input: string }>());\n\n    result.current.formState.errors;\n\n    act(() => {\n      result.current.setError('input', input);\n    });\n    expect(result.current.formState.errors).toEqual(output);\n    expect(result.current.formState.isValid).toBeFalsy();\n  });\n\n  it('should update isValid with setError', async () => {\n    const App = () => {\n      const {\n        formState: { isValid },\n        setError,\n      } = useForm({\n        mode: 'onChange',\n      });\n\n      return (\n        <div>\n          <button\n            type={'button'}\n 