+{"version":3,"sources":["/workspace/repo/src/__tests__/useForm/clearErrors.test.tsx"],"sourcesContent":["import React from 'react';\nimport {\n  act,\n  fireEvent,\n  render,\n  renderHook,\n  screen,\n  waitFor,\n} from '@testing-library/react';\n\nimport type { Control } from '../../types';\nimport { useForm } from '../../useForm';\nimport { useFormState } from '../../useFormState';\n\ndescribe('clearErrors', () => {\n  it('should remove error', () => {\n    const { result } = renderHook(() => useForm<{ input: string }>());\n    act(() => {\n      result.current.register('input');\n      result.current.setError('input', {\n        type: 'test',\n        message: 'message',\n      });\n    });\n\n    act(() => result.current.clearErrors('input'));\n\n    expect(result.current.formState.errors).toEqual({});\n  });\n\n  it('should remove nested error', () => {\n    const { result } = renderHook(() =>\n      useForm<{ input: { nested: string } }>(),\n    );\n    result.current.formState.errors;\n    act(() =>\n      result.current.setError('input.nested', {\n        type: 'test',\n      }),\n    );\n    expect(result.current.formState.errors.input?.nested).toBeDefined();\n    act(() => result.current.clearErrors('input.nested'));\n    expect(result.current.formState.errors.input?.nested).toBeUndefined();\n  });\n\n  it('should remove deep nested error and set it to undefined', async () => {\n    let currentErrors = {};\n\n    const Component = () => {\n      const {\n        register,\n        formState: { errors },\n        trigger,\n        clearErrors,\n      } = useForm<{\n        test: { data: string };\n      }>();\n\n      currentErrors = errors;\n      return (\n        <div>\n          <input type=\"text\" {...register('test.data', { required: true })} />\n          <button type={'button'} onClick={() => trigger()}>\n            submit\n          </button>\n          <button type={'button'} onClick={() => clearErrors(['test.data'])}>\n            clear\n          </button>\n        </div>\n      );\n    };\n\n    render(<Component />);\n\n    fireEvent.click(screen.getByRole('button', { name: 'submit' }));\n\n    await waitFor(() =>\n      expect(currentErrors).toEqual({\n        test: {\n          data: {\n            message: '',\n            ref: screen.getByRole('textbox'),\n            type: 'required',\n          },\n        },\n      }),\n    );\n\n    fireEvent.click(screen.getByRole('button', { name: 'clear' }));\n\n    expect(currentErrors).toEqual({});\n  });\n\n  it('should remove specified errors', () => {\n    const { result } = renderHook(() =>\n      useForm<{\n        input: string;\n        input1: string;\n        input2: string;\n        nest: { data: string; data1: string };\n      }>(),\n    );\n\n    result.current.formState.errors;\n\n    const error = {\n      type: 'test',\n      message: 'message',\n    };\n\n    act(() => {\n      result.current.register('input');\n      result.current.register('input1');\n      result.current.register('input2');\n      result.current.setError('input', error);\n      result.current.setError('input1', error);\n      result.current.setError('input2', error);\n\n      result.current.register('nest.data');\n      result.current.register('nest.data1');\n      result.current.setError('nest.data', error);\n      result.current.setError('nest.data1', error);\n    });\n\n    const errors = {\n      input: {\n        ...error,\n        ref: {\n          name: 'input',\n        },\n      },\n      input1: {\n        ...error,\n        ref: {\n          name: 'input1',\n        },\n      },\n      input2: {\n        ...error,\n        ref: {\n          name: 'input2',\n        },\n      },\n      nest: {\n        data: {\n          ...error,\n          ref: {\n            name: 'nest.data',\n          },\n        },\n        data1: {\n          ...error,\n          ref: {\n            name: 'nest.data1',\n          },\n        },\n      },\n    };\n    expect(result.current.formState.errors).toEqual(errors);\n\n    act(() => result.current.clearErrors(['input', 'input1', 'nest.data']));\n    expect(result.current.formState.errors).toEqual({\n      input2: errors.input2,\n      nest: {\n        data1: errors.nest.data1,\n      },\n    });\n  });\n\n  it('should remove all error', () => {\n    const { result } = renderHook(() =>\n      useForm<{ input: string; input1: string; input2: string }>(),\n    );\n\n    result.current.formState.errors;\n\n    const error = {\n      type: 'test',\n      message: 'message',\n    };\n    act(() => result.current.setError('input', error));\n    act(() => result.current.setError('input1', error));\n    act(() => result.current.setError('input2', error));\n    expect(result.current.formState.errors).toEqual({\n      input: {\n        ...error,\n        ref: undefined,\n        types: undefined,\n      },\n      input1: {\n        ...error,\n        ref: undefined,\n        types: undefined,\n      },\n      input2: {\n        ...error,\n        ref: undefined,\n        types: undefined,\n      },\n    });\n\n    act(() => result.current.clearErrors());\n    expect(result.current.formState.errors).toEqual({});\n  });\n\n  it('should prevent the submission if there is a custom error', async () => {\n    const submit = jest.fn();\n    const { result } = renderHook(() =>\n      useForm<{ data: string; whatever: string }>(),\n    );\n\n    result.current.register('data');\n\n    act(() => {\n      result.current.setError('whatever', { type: 'server' });\n    });\n\n    await act(async () => await result.current.handleSubmit(submit)());\n    expect(submit).not.toHaveBeenCalled();\n\n    act(() => {\n      result.current.clearErrors('whatever');\n    });\n\n    await act(async () => await result.current.handleSubmit(submit)());\n    expect(submit).toHaveBeenCalled();\n  });\n\n  it('should update isValid to true with setError', async () => {\n    const App = () => {\n      const {\n        formState: { isValid },\n        setError,\n        clearErrors,\n      } = useForm({\n        mode: 'onChange',\n      });\n\n      return (\n        <div>\n          <button\n            onClick={() => {\n              setError('test', { type: 'test' });\n            }}\n          >\n            setError\n          </button>\n\n          <button\n            onClick={() => {\n              clearErrors();\n            }}\n          >\n            clearError\n          </button>\n          {isValid ? 'yes' : 'no'}\n        </div>\n      );\n    };\n\n    render(<App />);\n\n    expect(await screen.findByText('yes')).toBeVisible();\n\n    fireEvent.click(screen.getByRole('button', { name: 'setError' }));\n\n    expect(await screen.findByText('no')).toBeVisible();\n\n    fireEvent.click(screen.getByRole('button', { name: 'clearError' }));\n\n    expect(await screen.findByText('no')).toBeVisible();\n  });\n\n  it('should be able to clear root error', () => {\n    const App = () => {\n      const { clearErrors } = useForm();\n\n      React.useEffect(() => {\n        clearErrors('root');\n        clearErrors('root.other');\n      }, [clearErrors]);\n\n      return null;\n    };\n\n    render(<App />);\n  });\n\n  it('should only notify subscribers for the cleared field when using exact: true', async () => {\n    let renderCountA = 0;\n    let renderCountB = 0;\n\n    const FieldA = ({\n      control,\n    }: {\n      control: Control<{ a: string; b: string }>;\n    }) => {\n      const { errors } = useFormState({\n        control,\n        name: 'a',\n        exact: true,\n      });\n      renderCountA++;\n      return <div data-testid=\"error-a\">{errors.a?.message || ''}</div>;\n    };\n\n    const FieldB = ({\n      control,\n    }: {\n      control: Control<{ a: string; b: string }>;\n    }) => {\n      const { errors } = useFormState({\n        control,\n        name: 'b',\n        exact: true,\n      });\n      renderCountB++;\n      return <div data-testid=\"error-b\">{errors.b?.message || ''}</div>;\n    };\n\n    const App = () => {\n      const { control, setError, clearErrors } = useForm<{\n        a: string;\n        b: string;\n      }>();\n\n      return (\n        <div>\n          <FieldA control={control} />\n          <FieldB control={control} />\n          <button onClick={() => setError('a', { message: 'error a' })}>\n            Set Error A\n          </button>\n          <button onClick={() => clearErrors('a')}>Clear Error A</button>\n        </div>\n      );\n    };\n\n    render(<App />);\n\n    // Initial render\n    const initialRenderA = renderCountA;\n    const initialRenderB = renderCountB;\n\n    // Set error on field 'a'\n    fireEvent.click(screen.getByRole('button', { name: 'Set Error A' }));\n\n    await waitFor(() => {\n      expect(screen.getByTestId('error-a')).toHaveTextContent('error a');\n    });\n\n    const afterSetErrorRenderA = renderCountA;\n    const afterSetErrorRenderB = renderCountB;\n\n    // FieldA should have re-rendered for setError('a')\n    expect(afterSetErrorRenderA).toBeGreaterThan(initialRenderA);\n    // FieldB should NOT have re-rendered for setError('a')\n    expect(afterSetErrorRenderB).toBe(initialRenderB);\n\n    // Clear error on field 'a'\n    fireEvent.click(screen.getByRole('button', { name: 'Clear Error A' }));\n\n    await waitFor(() => {\n      expect(screen.getByTestId('error-a')).toHaveTextContent('');\n    });\n\n    const afterClearErrorRenderA = renderCountA;\n    const afterClearErrorRenderB = renderCountB;\n\n    // FieldA should have re-rendered for clearErrors('a')\n    expect(afterClearErrorRenderA).toBeGreaterThan(afterSetErrorRenderA);\n    // FieldB should NOT have re-rendered for clearErrors('a') - this is the bug fix!\n    expect(afterClearErrorRenderB).toBe(afterSetErrorRenderB);\n  });\n});\n"],"names":["describe","it","result","renderHook","useForm","act","current","register","setError","type","message","clearErrors","expect","formState","errors","toEqual","input","nested","toBeDefined","toBeUndefined","currentErrors","Component","trigger","div","required","button","onClick","render","fireEvent","click","screen","getByRole","name","waitFor","test","data","ref","error","input1","input2","nest","data1","undefined","types","submit","jest","fn","handleSubmit","not","toHaveBeenCalled","App","isValid","mode","findByText","toBeVisible","React","useEffect","renderCountA","renderCountB","FieldA","control","useFormState","exact","data-testid","a","FieldB","b","initialRenderA","initialRenderB","getByTestId","toHaveTextContent","afterSetErrorRenderA","afterSetErrorRenderB","toBeGreaterThan","toBe","afterClearErrorRenderA","afterClearErrorRenderB"],"mappings":";;;;8DAAkB;wBAQX;yBAGiB;8BACK;;;;;;AAE7BA,SAAS,eAAe;IACtBC,GAAG,uBAAuB;QACxB,MAAM,EAAEC,MAAM,EAAE,GAAGC,IAAAA,kBAAU,EAAC,IAAMC,IAAAA,gBAAO;QAC3CC,IAAAA,WAAG,EAAC;YACFH,OAAOI,OAAO,CAACC,QAAQ,CAAC;YACxBL,OAAOI,OAAO,CAACE,QAAQ,CAAC,SAAS;gBAC/BC,MAAM;gBACNC,SAAS;YACX;QACF;QAEAL,IAAAA,WAAG,EAAC,IAAMH,OAAOI,OAAO,CAACK,WAAW,CAAC;QAErCC,OAAOV,OAAOI,OAAO,CAACO,SAAS,CAACC,MAAM,EAAEC,OAAO,CAAC,CAAC;IACnD;IAEAd,GAAG,8BAA8B;QAC/B,MAAM,EAAEC,MAAM,EAAE,GAAGC,IAAAA,kBAAU,EAAC,IAC5BC,IAAAA,gBAAO;QAETF,OAAOI,OAAO,CAACO,SAAS,CAACC,MAAM;QAC/BT,IAAAA,WAAG,EAAC,IACFH,OAAOI,OAAO,CAACE,QAAQ,CAAC,gBAAgB;gBACtCC,MAAM;YACR;QAEFG,OAAOV,OAAOI,OAAO,CAACO,SAAS,CAACC,MAAM,CAACE,KAAK,EAAEC,QAAQC,WAAW;QACjEb,IAAAA,WAAG,EAAC,IAAMH,OAAOI,OAAO,CAACK,WAAW,CAAC;QACrCC,OAAOV,OAAOI,OAAO,CAACO,SAAS,CAACC,MAAM,CAACE,KAAK,EAAEC,QAAQE,aAAa;IACrE;IAEAlB,GAAG,2DAA2D;QAC5D,IAAImB,gBAAgB,CAAC;QAErB,MAAMC,YAAY;YAChB,MAAM,EACJd,QAAQ,EACRM,WAAW,EAAEC,MAAM,EAAE,EACrBQ,OAAO,EACPX,WAAW,EACZ,GAAGP,IAAAA,gBAAO;YAIXgB,gBAAgBN;YAChB,qBACE,6BAACS,2BACC,6BAACP;gBAAMP,MAAK;gBAAQ,GAAGF,SAAS,aAAa;oBAAEiB,UAAU;gBAAK,EAAE;8BAChE,6BAACC;gBAAOhB,MAAM;gBAAUiB,SAAS,IAAMJ;eAAW,yBAGlD,6BAACG;gBAAOhB,MAAM;gBAAUiB,SAAS,IAAMf,YAAY;wBAAC;qBAAY;eAAG;QAKzE;QAEAgB,IAAAA,cAAM,gBAAC,6BAACN;QAERO,iBAAS,CAACC,KAAK,CAACC,cAAM,CAACC,SAAS,CAAC,UAAU;YAAEC,MAAM;