+{"version":3,"sources":["/workspace/repo/src/__tests__/useFieldArray/append.test.tsx"],"sourcesContent":["import React from 'react';\nimport {\n  act,\n  fireEvent,\n  render,\n  renderHook,\n  screen,\n  waitFor,\n} from '@testing-library/react';\n\nimport { VALIDATION_MODE } from '../../constants';\nimport type { Control, FieldPath } from '../../types';\nimport { useController } from '../../useController';\nimport { useFieldArray } from '../../useFieldArray';\nimport { useForm } from '../../useForm';\n\nlet i = 0;\n\njest.mock('../../logic/generateId', () => () => String(i++));\n\ndescribe('append', () => {\n  beforeEach(() => {\n    i = 0;\n  });\n\n  it('should append dirtyFields fields correctly', async () => {\n    let dirtyInputs = {};\n    const Component = () => {\n      const {\n        register,\n        control,\n        formState: { dirtyFields },\n      } = useForm<{\n        test: { value: string }[];\n      }>({\n        defaultValues: {\n          test: [\n            { value: 'plz change' },\n            { value: 'dont change' },\n            { value: 'dont change' },\n          ],\n        },\n      });\n      const { fields, append } = useFieldArray({\n        control,\n        name: 'test',\n      });\n\n      dirtyInputs = dirtyFields;\n\n      return (\n        <form>\n          {fields.map((field, i) => (\n            <input key={field.id} {...register(`test.${i}.value` as const)} />\n          ))}\n          <button type=\"button\" onClick={() => append({ value: '' })}>\n            append\n          </button>\n          {dirtyFields.test?.length && 'dirty'}\n        </form>\n      );\n    };\n\n    render(<Component />);\n\n    fireEvent.input(screen.getAllByRole('textbox')[0], {\n      target: { value: 'test' },\n    });\n    fireEvent.blur(screen.getAllByRole('textbox')[0]);\n\n    expect(await screen.findByText('dirty')).toBeVisible();\n\n    expect(dirtyInputs).toEqual({\n      test: [{ value: true }],\n    });\n\n    fireEvent.click(s