tyValue;\n\n      const Component = () => {\n        const {\n          register,\n          control,\n          formState: { isDirty, dirtyFields },\n        } = useForm<{\n          test: { test: string }[];\n        }>();\n        const { fields, append } = useFieldArray({\n          control,\n          name: 'test',\n        });\n\n        isDirtyValue = isDirty;\n        dirtyValue = dirtyFields;\n\n        return (\n          <form>\n            {fields.map((field, index) => {\n              return (\n                <input\n                  key={field.id}\n                  {...register(`test.${index}.test` as const)}\n                />\n              );\n            })}\n            <button type={'button'} onClick={() => append({ test: 'test' })}>\n              append\n            </button>\n          </form>\n        );\n      };\n\n      render(<Component />);\n\n      fireEvent.click(screen.getByRole('button', { name: 'append' }));\n\n      fireEvent.click(screen.getByRole('button', { name: 'append' }));\n\n      fireEvent.click(screen.getByRole('button', { name: 'append' }));\n\n      expect(isDirtyValue).toBeTruthy();\n      expect(dirtyValue).toEqual({\n        test: [{ test: true }, { test: true }, { test: true }],\n      });\n    },\n  );\n\n  it('should trigger reRender when user is watching the all field array', () => {\n    const watched: unknown[] = [];\n    const Component = () => {\n      const { register, watch, control } = useForm<{\n        test: { value: string }[];\n      }>();\n      const { fields, append } = useFieldArray({\n        control,\n        name: 'test',\n      });\n      watched.push(watch());\n\n      return (\n        <form>\n          {fields.map((field, i) => (\n            <input key={field.id} {...register(`test.${i}.value` as const)} />\n          ))}\n          <button type=\"button\" onClick={() => append({ value: '' })}>\n            append\n          </button>\n        </form>\n      );\n    };\n\n    render(<Component />);\n\n    fireEvent.click(screen.getByRole('button', { name: /append/i }));\n\n    expect(watched).toEqual([\n      {},\n      { test: [] },\n      { test: [{ value: '' }] },\n      { test: [{ value: '' }] },\n    ]);\n  });\n\n  it('should focus if shouldFocus is true', () => {\n    const Component = () => {\n      const { register, control } = useForm<{\n        test: { value: string }[];\n      }>({\n        defaultValues: { test: [{ value: '1' }, { value: '2' }] },\n      });\n      const { fields, append } = useFieldArray({ control, name: 'test' });\n\n      return (\n        <form>\n          {fields.map((field, i) => (\n            <input key={field.id} {...register(`test.${i}.value` as const)} />\n          ))}\n          <button type=\"button\" onClick={() => append({ value: '3' })}>\n            append\n          </button>\n        </form>\n      );\n    };\n\n    render(<Component />);\n\n    fireEvent.click(screen.getByRole('button', { name: /append/i }));\n\n    const inputs = screen.getAllByRole('textbox');\n\n    expect(inputs).toHaveLength(3);\n\n    expect(document.activeElement).toEqual(inputs[2]);\n  });\n\n  it('should not focus if shouldFocus is false', () => {\n    const Component = () => {\n      const { register, control } = useForm<{\n        test: { value: string }[];\n      }>({\n        defaultValues: { test: [{ value: '1' }, { value: '2' }] },\n      });\n      const { fields, append } = useFieldArray({ control, name: 'test' });\n\n      return (\n        <form>\n          {fields.map((field, i) => (\n            <input key={field.id} {...register(`test.${i}.value` as const)} />\n          ))}\n          <button\n            type=\"button\"\n            onClick={() => append({ value: '3' }, { shouldFocus: false })}\n          >\n            append\n          </button>\n        </form>\n      );\n    };\n\n    render(<Component />);\n\n    fireEvent.click(screen.getByRole('button', { name: /append/i }));\n\n    const inputs = sc