+{"version":3,"sources":["/workspace/repo/src/__tests__/useForm.test.tsx"],"sourcesContent":["import React, { useState } from 'react';\nimport {\n  act,\n  fireEvent,\n  render,\n  renderHook,\n  screen,\n  waitFor,\n  waitForElementToBeRemoved,\n} from '@testing-library/react';\n\nimport { VALIDATION_MODE } from '../constants';\nimport type {\n  Control,\n  FieldErrors,\n  FieldValues,\n  FormState,\n  Mode,\n  RegisterOptions,\n  SubmitHandler,\n  UseFormGetFieldState,\n  UseFormRegister,\n  UseFormReturn,\n  UseFormUnregister,\n} from '../types';\nimport isFunction from '../utils/isFunction';\nimport noop from '../utils/noop';\nimport sleep from '../utils/sleep';\nimport {\n  Controller,\n  createFormControl,\n  useFieldArray,\n  useForm,\n  useFormState,\n} from '../';\n\njest.useFakeTimers();\n\ndescribe('useForm', () => {\n  describe('when component unMount', () => {\n    it('should call unSubscribe', () => {\n      const { result, unmount } = renderHook(() => useForm<{ test: string }>());\n\n      result.current.register('test');\n      unmount();\n\n      expect(result.current.getValues()).toEqual({});\n    });\n\n    it('should remain array field values when inputs gets unmounted', () => {\n      const { result, unmount } = renderHook(() =>\n        useForm<{ test: string[] }>(),\n      );\n\n      result.current.register('test.0');\n      result.current.register('test.1');\n      result.current.register('test.2');\n\n      unmount();\n\n      expect(result.current.getValues()).toEqual({\n        test: [undefined, undefined, undefined],\n      });\n    });\n\n    it('should not unregister errors when unmounted', async () => {\n      const { result, unmount } = renderHook(() =>\n        useForm<{\n          test: string;\n        }>(),\n      );\n\n      result.current.formState.errors;\n      result.current.register('test', { required: true });\n\n      await act(async () => {\n        await result.current.handleSubmit(noop)({\n          preventDefault: noo