+{"version":3,"sources":["/workspace/repo/src/__tests__/useForm/resetField.test.tsx"],"sourcesContent":["import React from 'react';\nimport { fireEvent, render, screen } from '@testing-library/react';\n\nimport { useForm } from '../../useForm';\n\ndescribe('resetField', () => {\n  it('should reset input value', () => {\n    const App = () => {\n      const { register, resetField } = useForm({\n        defaultValues: {\n          test: 'test',\n        },\n      });\n\n      return (\n        <form>\n          <input {...register('test')} />\n          <button\n            type={'button'}\n            onClick={() => {\n              resetField('test');\n            }}\n          >\n            reset\n          </button>\n        </form>\n      );\n    };\n\n    render(<App />);\n\n    fireEvent.change(screen.getByRole('textbox'), {\n      target: {\n        value: '1234',\n      },\n    });\n\n    expect((screen.getByRole('textbox') as HTMLInputElement).value).toEqual(\n      '1234',\n    );\n\n    fireEvent.click(screen.getByRole('button'));\n\n    expect((screen.getByRole('textbox') as HTMLInputElement).value).toEqual(\n      'test',\n    );\n  });\n\n  it('should reset input touched field state', async () => {\n    const App = () => {\n      const {\n        register,\n        resetField,\n        formState: { touchedFields },\n      } = useForm({\n        defaultValues: {\n          test: 'test',\n        },\n      });\n\n      return (\n        <form>\n          <input {...register('test')} />\n          <p>{touchedFields.test ? 'touched' : 'noTouched'}</p>\n          <button\n            type={'button'}\n            onClick={() => {\n              resetField('test');\n            }}\n          >\n            reset\n          </button>\n        </form>\n      );\n    };\n\n    render(<App />);\n\n    fireEvent.focus(screen.getByRole('textbox'));\n\n    fireEvent.blur(screen.getByRole('textbox'));\n\n    expect(await screen.findByText('touched')).toBeVisible();\n\n    fireEvent.click(screen.getByRole('button'));\n\n    expect(await screen.findByText('noTouched')).toBeVisible();\n  });\n\n  it('should reset input dirty field and dirty state', async () => {\n    const App = () => {\n      const {\n        register,\n        resetField,\n        formState: { dirtyFields, isDirty },\n      } = useForm({\n        defaultValues: {\n          test: 'test',\n        },\n      });\n\n      return (\n        <form>\n          <input {...register('test')} />\n          <p>{dirtyFields.test ? 'dirty' : 'notDirty'}</p>\n          <p>{isDirty ? 'formDirty' : 'formNotDirty'}</p>\n          <button\n            type={'button'}\n            onClick={() => {\n              resetField('test');\n            }}\n          >\n            reset\n          </button>\n        </form>\n      );\n    };\n\n    render(<App />);\n\n    fireEvent.change(screen.getByRole('textbox'), {\n      target: {\n        value: '1234',\n      },\n    });\n\n    expect(await screen.findByText('dirty')).toBeVisible();\n    expect(screen.getByText('formDirty')).toBeVisible();\n\n    fireEvent.click(screen.getByRole('button'));\n\n    expect(await screen.findByText('notDirty')).toBeVisible();\n    expect(screen.getByText('formNotDirty')).toBeVisible();\n  });\n\n  it('should reset input error field and isValid state', async () => {\n    const App = () => {\n      const {\n        register,\n        resetField,\n        formState: { errors, isValid },\n      } = useForm({\n        defaultValues: {\n          test: 'test',\n        },\n        mode: 'onChange',\n      });\n\n      return (\n        <form>\n          <input {...register('test', { maxLength: 4 })} />\n          <p>{errors.test ? 'error' : 'noError'}</p>\n          <p>{isValid ? 'valid' : 'NotValid'}</p>\n          <button\n            type={'button'}\n            onClick={() => {\n              resetField('test');\n            }}\n          >\n            reset\n          </button>\n        </form>\n      );\n    };\n\n    render(<App />);\n\n    expect(await screen.findByText('valid')).toBeVisible();\n    expect(screen.getByText('noError')).toBeVisible();\n\n    fireEvent.change(screen.getByRole('textbox'), {\n      target: {\n        value: 'test12345',\n      },\n    });\n\n    expect(await screen.findByText('NotValid')).toBeVisible();\n    expect(screen.getByText('error')).toBeVisible();\n\n    fireEvent.click(screen.getByRole('button'));\n\n    expect(await screen.findByText('valid')).toBeVisible();\n    expect(screen.getByText('noError')).toBeVisible();\n  });\n\n  it('should reset input file to empty string only', () => {\n    const getValuesFn = jest.fn();\n\n    const App = () => {\n      const { register, resetField, getValues } = useForm({\n        defaultValues: {\n          test: '',\n        },\n      });\n\n      return (\n        <form>\n          <input type={'file'} {...register('test')} />\n          <button\n            type={'button'}\n            onClick={() => {\n              resetField('test', { defaultValue: '' });\n            }}\n          >\n            reset\n          </button>\n          <button\n            type={'button'}\n            onClick={() => {\n              getValuesFn(getValues());\n            }}\n          >\n            getValues\n          </button>\n        </form>\n      );\n    };\n\n    render(<App />);\n\n    fireEvent.click(screen.getByRole('button', { name: 'getValues' }));\n\n    expect(getValuesFn).toHaveBeenCalledWith({ test: '' });\n\n    fireEvent.click(screen.getByRole('button', { name: 'reset' }));\n\n    expect(getValuesFn).toHaveBeenCalledWith({ test: '' });\n  });\n\n  describe('when provided with options', () => {\n    it('should update input value and its defaultValue', () => {\n      const App = () => {\n        const { register, resetField } = useForm({\n          defaultValues: {\n            test: 'test',\n          },\n        });\n\n        return (\n          <form>\n            <input {...register('test')} />\n            <button\n              type={'button'}\n              onClick={() => {\n                resetField('test', {\n                  defaultValue: 'test1234',\n                });\n              }}\n            >\n              reset\n            </button>\n          </form>\n        );\n      };\n\n      render(<App />);\n\n      fireEvent.change(screen.getByRole('textbox'), {\n        target: {\n          value: '1234',\n        },\n      });\n\n      expect((screen.getByRole('textbox') as HTMLInputElement).value).toEqual(\n        '1234',\n      );\n\n      fireEvent.click(screen.getByRole('button'));\n\n      expect((screen.getByRole('textbox') as HTMLInputElement).value).toEqual(\n        'test1234',\n      );\n    });\n\n    it('should keep touched field state', async () => {\n      const App = () => {\n        const {\n          register,\n          resetField,\n          formState: { touchedFields },\n        } = useForm({\n          defaultValues: {\n            test: 'test',\n          },\n        });\n\n        return (\n          <form>\n            <input {...register('test')} />\n            <p>{touchedFields.test ? 'touched' : 'noTouched'}</p>\n            <button\n              type={'button'}\n              onClick={() => {\n                resetField('test', { keepTouched: true });\n              }}\n            >\n              reset\n            </button>\n          </form>\n        );\n      };\n\n      render(<App />);\n\n      fireEvent.focus(screen.getByRole('textbox'));\n\n      fireEvent.blur(screen.getByRole('textbox'));\n\n      expect(await screen.findByText('touched')).toBeVisible();\n\n      fireEvent.click(screen.getByRole('button'));\n\n      expect(await screen.findByText('touched')).toBeVisible();\n    });\n\n    it('should keep dirty field and isDirty state', async () => {\n      const App = () => {\n        const {\n          register,\n          resetField,\n          formState: { dirtyFields, isDirty },\n        } = useForm({\n          defaultValues: {\n            test: 'test',\n          },\n        });\n\n        return (\n          <form>\n            <input {...register('test')} />\n            <p>{dirtyFields.test ? 'dirty' : 'notDirty'}</p>\n            <p>{isDirty ? 'formDirty' : 'formNotDirty'}</p>\n            <button\n              type={'button'}\n              onClick={() => {\n                resetField('test', { keepDirty: true });\n              }}\n            >\n              reset\n            </button>\n          </form>\n        );\n      };\n\n      render(<App />);\n\n      fireEvent.change(screen.getByRole('textbox'), {\n        target: {\n          value: '1234',\n        },\n      });\n\n      expect(await screen.findByText('dirty')).toBeVisible();\n      expect(screen.getByText('formDirty')).toBeVisible();\n\n      fireEvent.click(screen.getByRole('button'));\n\n      expect(await screen.findByText('dirty')).toBeVisible();\n      expect(screen.getByText('formDirty')).toBeVisible();\n    });\n\n    it('should skip reset error field and isValid state', async () => {\n      const App = () => {\n        const {\n          register,\n          resetField,\n          formState: { errors, isValid },\n        } = useForm({\n          defaultValues: {\n            test: 'test',\n          },\n          mode: 'onChange',\n        });\n\n        return (\n          <form>\n            <input {...register('test', { maxLength: 4 })} />\n            <p>{errors.test ? 'error' : 'noError'}</p>\n            <p>{isValid ? 'valid' : 'NotValid'}</p>\n            <button\n              type={'button'}\n              onClick={() => {\n                resetField('test', { keepError: true });\n              }}\n            >\n              reset\n            </button>\n          </form>\n        );\n      };\n\n      render(<App />);\n\n      expect(await screen.findByText('valid')).toBeVisible();\n      expect(screen.getByText('noError')).toBeVisible();\n\n      fireEvent.change(screen.getByRole('textbox'), {\n        target: {\n          value: 'test12345',\n        },\n      });\n\n      expect(await screen.findByText('NotValid')).toBeVisible();\n      expect(screen.getByText('error')).toBeVisible();\n\n      fireEvent.click(screen.getByRole('button'));\n\n      expect(await screen.findByText('NotValid')).toBeVisible();\n      expect(screen.getByText('error')).toBeVisible();\n    });\n\n    it('should work with objects as defaultValue', async () => {\n      const App = () => {\n        const {\n          register,\n          resetField,\n          formState: { isDirty },\n        } = useForm({\n          defaultValues: {\n            nestedObjectTest: {\n              test: 'test',\n            },\n          },\n          mode: 'onChange',\n        });\n\n        return (\n          <form>\n            <input {...register('nestedObjectTest.test', { maxLength: 4 })} />\n            <p>{isDirty ? 'isDirty' : 'isNotDirty'}</p>\n            <button\n              type={'button'}\n              onClick={() => {\n                resetField('nestedObjectTest', {\n                  defaultValue: { test: 'test2' },\n                });\n              }}\n            >\n              reset\n            </button>\n          </form>\n        );\n      };\n\n      render(<App />);\n\n      expect(await screen.findByText('isNotDirty')).toBeVisible();\n\n      fireEvent.change(screen.getByRole('textbox'), {\n        target: {\n          value: 'abcd',\n        },\n      });\n\n      expect(await screen.findByText('isDirty')).toBeVisible();\n\n      fireEvent.click(screen.getByRole('button'));\n\n      fireEvent.change(screen.getByRole('textbox'), {\n        target: {\n          value: '1234',\n        },\n      });\n\n      expect(await screen.findByText('isDirty')).toBeVisible();\n    });\n  });\n});\n"],"names":["describe","it","App","register","resetField","useForm","defaultValues","test","form","input","button","type","onClick",