+{"version":3,"sources":["/workspace/repo/src/__tests__/useForm/getValues.test.tsx"],"sourcesContent":["import React from 'react';\nimport {\n  fireEvent,\n  render,\n  renderHook,\n  screen,\n  waitFor,\n} from '@testing-library/react';\n\nimport { Controller } from '../../controller';\nimport { useForm } from '../../useForm';\nimport { FormProvider, useFormContext } from '../../useFormContext';\nimport { useFormState } from '../../useFormState';\n\ndescribe('getValues', () => {\n  it('should return defaultValues before inputs mounted', () => {\n    let values;\n\n    const Component = () => {\n      const { getValues } = useForm({\n        defaultValues: {\n          test: 'test',\n        },\n      });\n\n      values = getValues();\n\n      return null;\n    };\n\n    const { rerender } = render(<Component />);\n\n    expect(values).toEqual({\n      test: 'test',\n    });\n\n    rerender(<Component />);\n\n    expect(values).toEqual({\n      test: 'test',\n    });\n  });\n\n  it('should call getFieldsValues and return all values', () => {\n    const { result } = renderHook(() => useForm<{ test: string }>());\n    result.current.register('test');\n    result.current.setValue('test', 'test');\n    expect(result.current.getValues()).toEqual({ test: 'test' });\n  });\n\n  it('should get individual field value', () => {\n    const { result } = renderHook(() =>\n      useForm<{ test: string }>({\n        defaultValues: {\n          test: '123',\n        },\n      }),\n    );\n    result.current.register('test');\n    expect(result.current.getValues('test')).toEqual('123');\n  });\n\n  it('should get all field values', () => {\n    const values = {\n      test: 'test',\n      test1: 'test1',\n      test2: 'test2',\n    };\n    const { result } = renderHook(() =>\n      useForm<{ test: string; test1: string; test2: string }>({\n        defaultValues: values,\n      }),\n    );\n    result.current.register('test');\n    result.current.register('test1');\n    result.current.register('test2');\n\n    result.current.setValue('test', 'test');\n    result.current.setValue('test1', 'test1');\n    result.current.setValue('test2', 'test2');\n\n    expect(result.current.getValues(['test', 'test1', 'test2'])).toEqual([\n      'test',\n      'test1',\n      'test2',\n    ]);\n  });\n\n  it('should get undefined when field not found', () => {\n    const { result } = renderHook(() => useForm());\n\n    expect(result.current.getValues('test')).toEqual(undefined);\n  });\n\n  it('should get value from shallowFieldsStateRef by name', () => {\n    const { result, unmount } = renderHook(() =>\n      useForm<{\n        test: string;\n      }>(),\n    );\n\n    result.current.register('test');\n    result.current.setValue('test', 'test');\n\n    unmount();\n\n    expect(result.current.getValues('test')).toEqual('test');\n  });\n\n  it('should get value from shallowFieldsStateRef by array', () => {\n    const { result, unmount } = renderHook(() =>\n      useForm<{\n        test: string;\n      }>(),\n    );\n\n    result.current.register('test');\n    result.current.setValue('test', 'test');\n\n    unmount();\n\n    expect(result.current.getValues(['test'])).toEqual(['test']);\n  });\n\n  it('should get value from shallowFieldsStateRef', () => {\n    const { result, unmount } = renderHook(() =>\n      useForm<{\n        test: string;\n      }>(),\n    );\n\n    result.current.register('test');\n    result.current.setValue('test', 'test');\n\n    unmount();\n\n    expect(result.current.getValues()).toEqual({\n      test: 'test',\n    });\n  });\n\n  it('should get value from default value by name when field is not registered', () => {\n    const { result } = renderHook(() =>\n      useForm({\n        defaultValues: {\n          test: 'default',\n        },\n      }),\n    );\n\n    expect(result.current.getValues('test')).toEqual('default');\n  });\n\n  it('should get value from default value by array when field is not registered', () => {\n    const { result } = renderHook(() =>\n      useForm({\n        defaultValues: {\n          test: 'default',\n        },\n      }),\n    );\n\n    expect(result.current.getValues(['test'])).toEqual(['default']);\n  });\n\n  it('should not get value from default value when field is not registered', () => {\n    const { result } = renderHook(() =>\n      useForm({\n        defaultValues: {\n          test: 'default',\n        },\n      }),\n    );\n\n    expect(result.current.getValues()).toEqual({\n      test: 'default',\n    });\n  });\n\n  it('should return defaultValues when inputs are not registered', () => {\n    let data: unknown;\n\n    const Component = () => {\n      const { getValues } = useForm({\n        defaultValues: {\n          test: 'test',\n        },\n      });\n\n      if (!data) {\n        data = getValues();\n      }\n\n      return null;\n    };\n\n    render(<Component />);\n\n    expect(data).toEqual({ test: 'test' });\n  });\n\n  it('should return defaultValues deep merge with form values', async () => {\n    let data: unknown;\n\n    const Component = () => {\n      const { getValues, register } = useForm({\n        defaultValues: {\n          test: {\n            firstName: 'test',\n            lastName: 'test',\n            time: new Date('1999-09-09'),\n            file: new File([''], 'filename'),\n          },\n        },\n      });\n\n      if (!data) {\n        data = getValues();\n      }\n\n      return (\n        <div>\n          <input {...register('test.firstName')} />\n          <button\n            onClick={() => {\n              data = getValues();\n            }}\n          >\n            getValues\n          </button>\n        </div>\n      );\n    };\n\n    render(<Component />);\n\n    expect(data).toEqual({\n      test: {\n        firstName: 'test',\n        lastName: 'test',\n        time: new Date('1999-09-09'),\n        file: new File([''], 'filename'),\n      },\n    });\n\n    fireEvent.change(screen.getByRole('textbox'), {\n      target: {\n        value: '1234',\n      },\n    });\n\n    fireEvent.click(screen.getByRole('button'));\n\n    expect(data).toMatchObject({\n      test: {\n        firstName: '1234',\n        lastName: 'test',\n      },\n    });\n  });\n\n  it('should return mounted input value after async reset', async () => {\n    let updatedValue: unknown;\n\n    type FormValues = {\n      firstName: string;\n    };\n\n    function Form() {\n      const { handleSubmit, reset, getValues } = useFormContext();\n      const { isDirty, isValid } = useFormState();\n\n      return (\n        <form\n          onSubmit={handleSubmit(async (data) => {\n            await Promise.resolve();\n            reset(data);\n          })}\n        >\n          <button\n            type={'button'}\n            onClick={() => {\n              updatedValue = getValues();\n            }}\n          >\n            getValues\n          </button>\n          <button type=\"submit\" disabled={!isDirty || !isValid}>\n            submit\n          </button>\n\n          <Controller\n            name=\"firstName\"\n            rules={{ required: true }}\n            render={({ field }) => <input {...field} />}\n          />\n        </form>\n      );\n    }\n\n    function App() {\n      const methods = useForm<FormValues>({\n        defaultValues: {\n          firstName: 'test',\n        },\n      });\n\n      return (\n        <FormProvider {...methods}>\n          <Form />\n        </FormProvider>\n      );\n    }\n\n    render(<App />);\n\n    fireEvent.change(screen.getByRole('textbox'), {\n      target: { value: 'test1' },\n    });\n\n    fireEvent.click(screen.getByRole('button', { name: 'submit' }));\n\n    expect(screen.getByRole('button', { name: 'submit' })).toBeDisabled();\n\n    fireEvent.change(screen.getByRole('textbox'), {\n      target: { value: 'test2' },\n    });\n\n    await waitFor(() =>\n      expect(screen.getByRole('button', { name: 'submit' })).not.toBeDisabled(),\n    );\n\n    fireEvent.click(screen.getByRole('button', { name: 'getValues' }));\n\n    expect(updatedValue).toEqual({\n      firstName: 'test2',\n    });\n\n    fireEvent.change(screen.getByRole('textbox'), {\n      target: { value: 'test3' },\n    });\n\n    expect(screen.getByRole('button', { name: 'submit' })).not.toBeDisabled();\n  });\n});\n"],"names":["describe","it","values","Component","getValues","useForm","defaultValues","test","rerender","render","expect","toEqual","result","renderHook","current","register","setValue","test1","test2","undefined","unmount","data","firstName","lastName","time","Date","file","File","div","input","button","onClick","fireEvent","change","screen","getByRole","target","value","click","toMatchObject","updatedValue","Form","handleSubmit","reset","useFormContext","isDirty","isValid","useFormState","form","onSubmit","Promise","resolve","type","disabled","Controller","name","rules","required","field","App","methods","FormProvider","toBeDisabled","waitFor","not"],"mappings":";;;;8DAAkB;wBAOX;4BAEoB;yBACH;gCACqB;8BAChB;;;;;;AAE7BA,SAAS,aAAa;IACpBC,GAAG,qDAAqD;QACtD,IAAIC;QAEJ,MAAMC,YAAY;YAChB,MAAM,EAAEC,SAAS,EAAE,GAAGC,IAAAA,gBAAO,EAAC;gBAC5BC,eAAe;oBACbC,MAAM;gBACR;YACF;YAEAL,SAASE;YAET,OAAO;QACT;QAEA,MAAM,EAAEI,QAAQ,EAAE,GAAGC,IAAAA,cAAM,gBAAC,6BAACN;QAE7BO,OAAOR,QAAQS,OAAO,CAAC;YACrBJ,MAAM;QACR;QAEAC,uBAAS,6BAACL;QAEVO,OAAOR,QAAQS,OAAO,CAAC;YACrBJ,MAAM;QACR;IACF;IAEAN,GAAG,qDAAqD;QACtD,MAAM,EAAEW,MAAM,EAAE,GAAGC,IAAAA,kBAAU,EAAC,IAAMR,IAAAA,gBAAO;QAC3CO,OAAOE,OAAO,CAACC,QAAQ,CAAC;QACxBH,OAAOE,OAAO,CAACE,QAAQ,CAAC,QAAQ;QAChCN,OAAOE,OAAOE,OAAO,CAACV,SAAS,IAAIO,OAAO,CAAC;YAAEJ,MAAM;QAAO;IAC5D;IAEAN,GAAG,qCAAqC;QACtC,MAAM,EAAEW,MAAM,EAAE,GAAGC,IAAAA,kBAAU,EAAC,IAC5BR,IAAAA,gBAAO,EAAmB;gBACxBC,eAAe;oBACbC,MAAM;gBACR;YACF;QAEFK,OAAOE,OAAO,CAACC,QAAQ,CAAC;QACxBL,OAAOE,OAAOE,OAAO,CAACV,SAAS,CAAC,SAASO,OAAO,CAAC;IACnD;IAEAV,GAAG,+BAA+B;QAChC,MAAMC,SAAS;YACbK,MAAM;YACNU,OAAO;YACPC,OAAO;QACT;QACA,MAAM,EAAEN,MAAM,EAAE,GAAGC,IAAAA,kBAAU,EAAC,IAC5BR,IAAAA,gB